"import express, { Request, Response } from 'express';
import cors from 'cors';
import dotenv from 'dotenv';
import path from 'path';
import multer from 'multer';
import { PrismaClient } from '@prisma/client';
import { uploadService } from './services/upload.service.js';

dotenv.config();

const app = express();
const prisma = new PrismaClient();
const PORT = process.env.PORT || 5000;

// Multer in-memory storage for handling file uploads before FTP transfer
const upload = multer({
  storage: multer.memoryStorage(),
  limits: { fileSize: 10 * 1024 * 1024 } // 10MB limit
});

// Middleware
const allowedOrigins = (process.env.CORS_ORIGIN || 'http://localhost:5173').split(',');
app.use(cors({
  origin: (origin, callback) => {
    if (!origin || allowedOrigins.includes(origin) || allowedOrigins.includes('*')) {
      callback(null, true);
    } else {
      callback(null, true); // Allow all in dev mode
    }
  },
  credentials: true
}));

app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// Serve local uploads in dev mode
app.use('/uploads', express.static(path.join(process.cwd(), 'uploads')));

// Helper to serialize BigInt
function serializeData(data: any): any {
  return JSON.parse(JSON.stringify(data, (_, value) =>
    typeof value === 'bigint' ? Number(value) : value
  ));
}

// Health check endpoint
app.get('/api/health', async (req: Request, res: Response) => {
  let dbStatus = 'disconnected';
  let totalProducts = 0;
  try {
    totalProducts = await prisma.product.count();
    dbStatus = 'connected';
  } catch (err) {
    dbStatus = 'error: ' + (err as Error).message;
  }

  res.json({
    status: 'ok',
    project: 'Filmiliar API',
    version: '1.0.0',
    database: {
      status: dbStatus,
      totalProductModels: totalProducts
    },
    storageMode: process.env.STORAGE_MODE || 'http_api'
  });
});

